from ic_lib import *

def face(col, ears, muzzle=None, nosecol=BLK, cx=16, cy=17, rr=11.5):
    s = ears + c(cx, cy, rr, col)
    if muzzle: s += e(cx, cy + 4.5, 6, 4.6, muzzle)
    return s + dot(cx - 4.5, cy - 2, 1.6) + dot(cx + 4.5, cy - 2, 1.6) + e(cx, cy + 3, 2, 1.5, nosecol)

